import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.1, E: 100, F: 100.5 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(base, items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// Characterization tests: pin CURRENT behavior, including questionable parts (see NOTE).
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple items summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 70],
  ['exactly 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 gets 10% off (NOTE: 100.5 -> 90.45 -> floored to 90)', [{ sku: 'F', qty: 1 }], 90],
  ['150 -> 135', [{ sku: 'B', qty: 6 }], 135],
  ['large order 1000 -> 900', [{ sku: 'E', qty: 10 }], 900],
  ['large mixed order 10*100 + 3*25 = 1075 -> 967.5 -> 967 (NOTE: floor, not round)', [{ sku: 'E', qty: 10 }, { sku: 'B', qty: 3 }], 967],
  ['fractional price, no discount: 3*33.33 = 99.99 -> 99 (NOTE: floored)', [{ sku: 'C', qty: 3 }], 99],
  ['fractional price with discount: 4*33.33 = 133.32 -> 119.988 -> 119', [{ sku: 'C', qty: 4 }], 119],
  ['float imprecision: 1001 * 0.1 -> 100.10000000000001 -> 90', [{ sku: 'D', qty: 1001 }], 90],
]

for (const [name, items, expected] of cases) {
  test(name, () => withApp(async (base) => {
    assert.equal(await totalFor(base, items), expected)
  }))
}

test('stored order returns the same total', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'E', qty: 10 }] }) })
  const { id } = await res.json()
  const got = await (await fetch(`${base}/orders/${id}`)).json()
  assert.equal(got.total, 900)
}))

test('empty items rejected', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
}))
EOF
