  ['fractional price, no discount: 3*33.33 = 99.99 -> 99 (NOTE: floored)', [{ sku: 'C', qty: 3 }], 99],
  ['fractional price with discount: 4*33.33 = 133.32 -> 119.988 -> 119', [{ sku: 'C', qty: 4 }], 119],
  ['float imprecision: 1001 * 0.1 -> 100.10000000000001 -> 90', [{ sku: 'D', qty: 1001 }], 90],
]

for (const [name, items, expected] of cases) {
  test(name, () => withApp(async (base) => {
    assert.equal(await totalFor(base, items), expected)
  }))
}

test('stored order returns the same total', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'E', qty: 10 }] }) })
  const { id } = await res.json()
  const got = await (await fetch(`${base}/orders/${id}`)).json()
  assert.equal(got.total, 900)
}))

